const lead = $input.first().json.body ?? $input.first().json;
const required = ['company_name','source_url','contact_basis'];
const missing = required.filter(k => !String(lead[k] ?? '').trim());
const urlOk = /^https?:\/\//i.test(String(lead.source_url ?? ''));
const approved = lead.outreach_approved === true && lead.opt_in === true;
if (missing.length || !urlOk || !approved) return [];
return [{json:{...lead, company_name:String(lead.company_name).trim().slice(0,240), contact_email:String(lead.contact_email ?? '').trim().slice(0,254), telegram_chat_id:String(lead.telegram_chat_id ?? '').trim().slice(0,100), product_or_order_signal:String(lead.product_or_order_signal ?? '').trim().slice(0,1000), source_url:String(lead.source_url).trim().slice(0,2000)}}];
